/bin/bash -lc "python - <<'PY'
try:
 from PyQt5.QtCore import QVersionNumber, QLibraryInfo
 print('Qt', QLibraryInfo.version().toString())
 for s in ['5.4', '5.4.0', '2.0.0.dev1', 'v2.3.4', '14.04', '538.1']:
  print(s, QVersionNumber.fromString(s))
except Exception as e: print(type(e).__name__, e)
PY"

